 constructor(dataset={}){this.dataset=dataset;this.textContent='';this.innerHTML='';this.value='';this.hidden=false;this.handlers={};this.classList={add(){},remove(){},toggle(){}};this.attrs={};this.open=false;}
 addEventListener(event,fn){(this.handlers[event]??=[]).push(fn)}
 click(){(this.handlers.click||[]).forEach(f=>f({target:this,preventDefault(){}}));if(this.onclick)this.onclick()}
 setAttribute(k,v){this.attrs[k]=v}removeAttribute(k){delete this.attrs[k]}
 showModal(){this.open=true}close(){this.open=false}scrollIntoView(){}reset(){}reportValidity(){return true}setCustomValidity(){}getBoundingClientRect(){return{left:0,right:500,top:0,bottom:500}}
}
const elements={},storage={},groups={};for(const match of html.matchAll(/id=\"(["'^"]+)"/g))elements['"'#'+match[1]]=new Element();
for(const key of ['filter','nav','count'])groups["'`[data-${key}]`]=[...html.matchAll(new RegExp(`data-${key}="([''^"]+)"`,'"'g'))].map(m=>new Element({[key]:m[1]}));
groups['.brand']=[new Element(),new Element()];groups['[data-close]']=[];groups.dialog=[elements['#create-dialog'],elements['#detail-dialog']];
const get=s=>{const match=s.match(/"'^'"\\[data-nav=\"(["'^'"\\\"]+)\"\\]"'$/);if(match)return groups['"'[data-nav]'].find(e=>e.dataset.nav===match[1]);return elements[s]??=new Element()};
let formValues={};const ctx=vm.createContext({console,structuredClone,Intl,Date,Number,String,JSON,Math,Array,Blob,URL,FormData:class{get(k){return formValues[k]}},setTimeout:()=>1,clearTimeout(){},localStorage:{getItem:k=>storage[k]??null,setItem:(k,v)=>storage[k]=v},document:{querySelector:get,querySelectorAll:s=>groups[s]||[],createElement:()=>new Element()},window:{scrollTo(){}}});
vm.runInContext(script,ctx);const run=s=>vm.runInContext(s,ctx);
assert.equal(run('invoices.length'),8);assert.match(elements['#total-outstanding'].innerHTML,/12,850/);assert.match(elements['#total-overdue'].innerHTML,/3,200/);assert.match(elements['#total-paid'].innerHTML,/6,000/);
run(\"setFilter('overdue')\");assert.equal(run('displayed().length'),2);assert.ok(run(\"displayed().every(i=>i.status==='overdue')\"));
run(\"filter='all';query='northline';render()\");assert.equal(run('displayed()[0].client'),'Northline Digital');
run(\"query='no matching client';render()\");assert.equal(elements['#empty'].hidden,false);
run(\"query='';filter='all';sortMode='highest'\");assert.equal(run('displayed()[0].amount'),4800);
formValues={client:'Pine & Paper',project:'Website refresh',amount:'2250.50',due:'2026-11-12',status:'pending'};
elements['#invoice-form'].handlers.submit[0]({preventDefault(){},currentTarget:elements['#invoice-form']});
assert.equal(run('invoices.length'),9);assert.match(elements['#total-outstanding'].innerHTML,/15,100/);assert.equal(JSON.parse(storage['folio-invoices-v1'])[0].client,'Pine & Paper');
run(\"openDetail('INV-2026-029')\");assert.equal(elements['#detail-dialog'].open,true);elements['#mark-paid'].onclick();assert.match(elements['#total-outstanding'].innerHTML,/12,850/);assert.match(elements['#total-paid'].innerHTML,/8,250/);assert.equal(run('invoices[0].status'),'paid');
formValues={client:'Past Due Design',project:'Consulting',amount:'100',due:'2026-10-01',status:'pending'};elements['#invoice-form'].handlers.submit[0]({preventDefault(){},currentTarget:elements['#invoice-form']});assert.equal(run('invoices[0].status'),'overdue');assert.match(elements['#total-overdue'].innerHTML,/3,300/);
run(\"query='<script>';filter='all';render()\");assert.equal(run('displayed().length'),0);
console.log('Passed: summary calculations, status filtering, search, empty state, sorting, invoice creation, persistence, payment recording, overdue classification.');
